// Step 1: move fetch out of the component
// before: component does fetch + parsing + error toasts

// after: a service owns the call, a composable owns the state
export function useOrders() {
  const orders = ref<Order[] | null>(null)
  const error = ref<string | null>(null)
  async function load() {
    try { orders.value = await ordersApi.list() }
    catch (e) { error.value = String(e) }
  }
  return { orders, error, load }
}
